-- College Scorecard cost year (2026-11-03). GENERATED from data/colleges/*.json by comparing the cost_aid rows
-- scripts/build_seed.py builds; do not hand-edit.
--
-- Why: the College Scorecard file released 2026-10-15 holds 2025-26 charges, not 2023-24 (Virginia Tech's in-state
-- tuition $16,450 matches neither College Navigator's 2023-24 $15,478 nor 2024-25 $15,948; Berea, Pitzer and Scripps
-- match their own published 2025-26 tables exactly). These 83 colleges' cost blocks were labelled 2023-2024 although
-- every number (tuition, out-of-state tuition, books, room and board, other, total cost) equals the institution's row in
-- that file, checked by script. Numbers are unchanged; only cost_aid.year ('2023-2024' -> '2025-2026') and the note's
-- "College Scorecard (IPEDS 2023-24): ..." prefix change. Matches data/** in the same commit.
--
-- One UPDATE keyed by college slug and year = '2023-2024'. It sets each row's whole note to what build_seed.py now
-- builds, so it also brings these rows' aid text up to 2026-10-30-student-facing-notes.sql (still unapplied on
-- 2026-11-03). Either order ends in the same state: run 2026-10-30-student-facing-notes.sql first if you can; if it runs
-- after this file, its final check counts these 80 cost_aid rows as not updated (they no longer have year 2023-2024),
-- which is expected. Running this file twice is harmless (the second run updates 0 rows and the check still passes).
-- Run it in the Supabase SQL Editor (or: psql "$DATABASE_URL" -f <this file>). The guard aborts (nothing changes)
-- unless all 83 rows end with the new year and note; the final SELECT should return ok = expected = 83.

begin;

update public.cost_aid t
set year = '2025-2026', notes = v.notes
from public.institutions i, (values
  ('american', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance.'),
  ('amherst', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-blind for all students including international; meets 100% of calculated need with no loans. 82% of international students receive aid (average award over $84,000 in 2025-26).'),
  ('arizona', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International students do not qualify for federal Title IV aid. Everyone is considered for merit tuition scholarships when they apply; apply by the Nov 1 Early Action deadline for priority.'),
  ('babson', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Admission is need-aware for international financial aid applicants. Need-based aid is limited to the Global Scholars program (four-year full-tuition scholarships plus extra grants based on need, for ED or RD applicants who file the CSS Profile) and the Canadian Scholarship. All international applicants are also considered for merit awards (Women''s Leadership quarter-tuition, Presidential half-tuition, Weissman full-tuition via separate application).'),
  ('barnard', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Barnard will meet 100% of the financial need of admitted students. Admissions is need-blind for U.S. citizens and permanent residents and need-aware for non-U.S. citizens and non-permanent residents.'),
  ('binghamton', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; The scholarships page says all applicants are considered automatically (President''s, Provost''s, Dean''s, Achievement scholarships; no separate application) but does not say whether international students are eligible, so no international aid policy is recorded. International admits must document funds for the first year before an I-20 is issued.'),
  ('bowdoin', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-blind for international students and meets the full calculated need of every admitted student, with no loans in aid packages. Beginning with the Class of 2031, international applicants (excluding Canadians) submit aid materials (CSS Profile, code 3089) only after being admitted. International transfer students are not eligible for institutional aid.'),
  ('brandeis', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Brandeis scholarships for international students are based on academic and personal records and are need-sensitive; competition is strong. Scholarship funds are generally awarded only at admission, and international students must reapply for aid each year with the CSS Profile (school code 3092). The Wien International Scholarship meets the full demonstrated need of each recipient; there is no separate application. Whether Brandeis meets full need for all international admits is not stated.'),
  ('brown', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-blind for international students beginning with the Class of 2029; meets full demonstrated need for admitted students who apply for aid at the time of application. No merit awards.'),
  ('buffalo', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UB offers scholarships in varying amounts to incoming first-year international students with no prior college credit (fall or spring entry), renewable up to four years; all admitted international students are automatically considered. The scholarships page does not mention need-based aid for international students, so that is left unconfirmed.'),
  ('case-western', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; The international page states financial aid is available to international students, all undergraduates are automatically evaluated for several scholarships (including full-tuition awards via scholarship competitions that need an essay), and CWRU awarded $213 million in institutional aid last year. Whether need is met in full for international students, and whether admission is need-blind, is not stated on the pages checked, so the aid policy is not shown.'),
  ('claremont-mckenna', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-aware for all international applicants; if admitted, CMC commits to meeting demonstrated need as determined at admission. Applicants must request aid on the application and submit the CMC Financial Aid Application for International Students (IFSAA and CSS Profile not accepted). Students not receiving aid at admission are not eligible later. Merit scholarships are available to first-year applicants (priority: application by Dec 1), no separate application.'),
  ('clemson', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; The international page states there are no scholarships for international undergraduates at Clemson and that deferred payment is not available. Sister-State agreements give in-state tuition to citizens of some German states, Queensland (Australia) and the Province of Taiwan.'),
  ('columbia', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Columbia meets the full demonstrated need of admitted first-years and has no merit scholarships. US citizens are need-blind; the international page notes that aid-seeking international candidates can fall outside the need-blind category, i.e. need-aware.'),
  ('cornell', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International admission is need-aware. Cornell meets 100% of admitted international undergraduates'' demonstrated need (grants, work-study and student loans). Apply for aid at the time of admission application with the CSS Profile (code 2098).'),
  ('cu-boulder', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Non-US citizens are not eligible for federal aid and CU Boulder offers no direct loans. All international first-year applications with complete documents by Jan. 15 (and English proficiency on file) are automatically reviewed for the Chancellor''s Achievement Scholarship and the Presidential Scholarship; no SAT/ACT needed. Full scholarships are rare (athletics; College of Music offers tuition awards).'),
  ('drexel', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Drexel offers need-based aid to qualifying international students (CSS Profile required by the deadline). Merit scholarship details for international students were not confirmed on the pages opened.'),
  ('duke', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Duke admits U.S. citizens, permanent residents and a limited number of international students without regard to financial circumstance and meets 100% of each admitted student''s demonstrated need; it expects to enroll 20 to 25 international students with full need met each year. All aid applicants submit the CSS Profile.'),
  ('emory', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Emory offers need-based aid to ''a select group'' of international students each year. International students must apply for aid during the admission process and apply Regular Decision to be considered for need-based aid; CSS Profile required. Limited merit scholarships are available to international students through the Emory University Scholar programs (apply before December). Whether Emory meets full need for international students is not stated on this page.'),
  ('florida-state', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Admitted international first-years are automatically considered for FSU''s out-of-state tuition waiver scholarship; students are told of offers with their admission decision. No need-based aid for international students is described.'),
  ('fordham', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Review of non-immigrant international applicants is need aware. Partial merit scholarships up to $25,000 (no extra application, for those not applying for need-based aid). Need-based aid goes to a limited number of first-year fall international students who indicate need on the Common App, can demonstrate a family contribution of at least $50,000/yr, and submit the CSS Profile by the application deadline. Awards stay the same for four years.'),
  ('georgetown', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Admitted international applicants who request aid are considered for a very limited number of need-based scholarships; Georgetown''s 100%-of-need commitment covers US citizens and permanent residents. No academic or merit scholarships. CSS Profile required; aid notifications go out by the first week of April. The pages read do not say whether admission is need-blind or need-aware for international applicants.'),
  ('gwu', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International students are not eligible for need-based financial assistance but are eligible for merit scholarships with no additional application; any merit award is noted in the admission letter.'),
  ('harvey-mudd', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Aid goes to a small number of admitted international applicants; financial need may affect admission chances. HMC states it can meet 100% of demonstrated need for only a handful of international students. Students who enter without aid are not considered for aid later. Merit: the So International Scholarship (one recipient per entering class, offered regardless of need, no separate application); international students may also apply for some merit awards.'),
  ('indiana', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International students are eligible for IU merit scholarships (judged from the admission application, deadline Nov 1 for IU scholarships, Feb 1 for international-student merit awards) and some country-specific awards. They cannot use US federal loans. The pages do not describe need-based institutional aid for international freshmen.'),
  ('johns-hopkins', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-based and merit scholarships are available to international applicants, but both are limited. You must apply for aid as a first-year applicant (no aid later); no aid for international transfer students. The page does not state whether admission is need-aware or whether full need is met for international students.'),
  ('lehigh', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Lehigh has limited international financial aid and "is need-aware in the admissions process" for non-U.S. citizens; some applicants who apply for aid but show no need may be admitted without an aid offer. Aid packages range from a few thousand dollars to full tuition, room and board, with no additional aid after the initial offer. Merit scholarships range from $5,000 to full tuition with no separate application. CSS Profile required by the application deadline for any applicant who will need aid in any year.'),
  ('miami', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UM is need-aware for first-year and transfer international applicants. International students who want to be considered for financial aid must submit the CSS Profile (school code 5815) by the financial aid deadline. The page does not say whether full demonstrated need is met for international students. All applicants are considered for merit scholarships (EA and ED I applicants also for Premier Scholarships).'),
  ('michigan-state', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International students are not eligible for aid through FAFSA. All admitted international students are automatically considered for the MSU Non-resident Scholarship ($3,000 to $18,000 a year, award levels by academic performance; decisions by mid-February); applying by Nov 1 gives maximum consideration.'),
  ('middlebury', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-aware in admission of international students; international students seeking aid must apply for it when they apply for admission. Middlebury meets 100% of demonstrated need for admitted students. CSS Profile (code 3526) required; the ISFAA and paper CSS Profile are not accepted. The pages checked describe need-based aid only; merit awards not confirmed.'),
  ('northeastern', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International students are not eligible for need-based aid (institutional grants or federal aid). They are eligible for merit scholarships, which are extremely competitive and do not cover the full cost of attendance; the admission application serves as the scholarship application.'),
  ('northwestern', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International admission review is need-aware (a request for aid and the amount needed may factor into the decision). Northwestern meets 100% of demonstrated need.'),
  ('notre-dame', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Notre Dame states its undergraduate admission evaluation is need-blind for international applicants. International first-years seeking need-based aid must complete the CSS Profile. The pages read do not say whether full demonstrated need is met for international students or describe merit scholarships.'),
  ('ohio-state', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Columbus university-funded first-year merit scholarships: "International students are not eligible." International students are generally not eligible for federal, state or most institutional funding.'),
  ('penn-state', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; "There is, at this time, essentially no financial aid available for international undergraduate students." Penn State Global lists two small tuition grants (SIGIA, PSTAG) for current students, typically $100 to $2,000.'),
  ('pitt', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Financial aid is not available to international students. International first-year fall applicants with a complete application by Feb 1 are automatically reviewed for scholarships of up to $10,000 per year (generally eight full-time terms). Proof of financial support required upon admission.'),
  ('pomona', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Admission is need-aware for international applicants, but Pomona meets 100% of demonstrated need of every admitted international student, without loans in the package. No merit or athletic scholarships. Aid must be requested when applying; it cannot be added after the admission application is submitted. About 41% of international students receive aid (average nearly $74,000/yr).'),
  ('princeton', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-blind for all applicants including international; full demonstrated need met with grants (no loans). No merit scholarships. Same aid policy regardless of citizenship.'),
  ('rice', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Rice considers international applicants on a need-aware basis and offers need-based aid to a limited number of international first-years; request aid on the International Student Financial Statement at application (aid cannot be requested later). Uses the CSS Profile for international aid applicants. Merit scholarships are separate, based only on merit, about 20% of admitted students receive them, no separate application. The page does not say whether full need is met for international students (the first-year page says domestic applicants are need-blind with 100% of need met without loans).'),
  ('rit', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International first-year applicants are considered for merit scholarships at admission (SAT/ACT encouraged); full-tuition scholarships are not available. RIT need-based grants are awarded from FAFSA results (CSS Profile not used), and the need-based page describes extra need-based aid only for Canadian students. I-20 requires documented support of at least $78,000 USD.'),
  ('rochester', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; The university states it is committed to meeting the full demonstrated need of all admitted students regardless of citizenship, but financial need is a contributing factor for international applicants, admission is highly selective for students with need, and only a small number of international applicants will qualify for need-based aid. Applicants who cannot secure funding for the cost of attendance cannot be admitted. All applicants are considered for merit scholarships with no extra paperwork. Limited CSS Profile fee waivers are available (request by Jan 15).'),
  ('rpi', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; "Limited merit scholarship opportunities" for undergraduate international students, up to $20,000 per year; all non-U.S. citizens/permanent residents must be prepared to pay the full cost of attendance. After enrolling, F-1/J-1 students must submit the International Student Financial Statement showing about one year of liquid funds (approx. $80,000 USD).'),
  ('rutgers', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; All admitted first-year international students on non-immigrant visas are automatically considered for Rutgers international merit scholarships ($5,000-$16,000 per year, four years, 3.25 GPA to renew); no separate application. Apply by the EA or RD date to be considered.'),
  ('santa-clara', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; SCU is need-aware for international students and offers no need-based financial aid. International first-year students are eligible for merit scholarship consideration (except the Johnson Scholars); no separate application, all Common App applicants are considered.'),
  ('smu', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; All applicants regardless of citizenship are automatically considered for academic merit scholarships (no separate application). Need-based financial aid is available only for US citizens and permanent residents.'),
  ('stevens', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International students are not eligible for federal aid; Stevens awards a limited number of merit scholarships to international students. The CSS Profile (code 2819) is required to be considered for institutional scholarships. Whether international applicants receive need-based grants is not stated on the page.'),
  ('stony-brook', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Not confirmed for international students: the scholarships page says all incoming first-year applicants are considered for merit scholarships (most need no separate application) and mentions the FAFSA for need-based awards, but it does not say whether international students are eligible. Admitted international students must document proof of financial support for one year to receive an I-20.'),
  ('swarthmore', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Admission is need-aware for international citizens. Admitted international students who applied for aid get 100% of demonstrated need (up to full tuition, with a $800 book allowance), as grants with no loans. Aid must be requested on the admission application. CSS Profile (code 2821) and the ISAFA form are due within 7 days of the admission decision. International students in the Class of 2030 and later get a four-year aid decision.'),
  ('syracuse', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; "International undergraduate students are considered for merit-based scholarships based on their application for admission," awarded by the Office of Admissions at the time of admission. The financial aid page describes no need-based aid for international students; FAFSA and CSS Profile are only for U.S. citizens and eligible noncitizens. F-1 applicants must show proof of liquid funds for one full academic year.'),
  ('texas-am', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; F-1 students are not eligible for need-based state aid (ITPEG, up to $4,000) in their first academic year; they may apply in later years through the TASFA. International students enrolled at College Station may be considered for university scholarships via the University Scholarship Application. No aid for entering international first-years was found.'),
  ('tufts', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Tufts meets 100% of demonstrated need for all admitted students regardless of citizenship, but only ''a limited amount of funding'' is available to international students and aid must be requested at the time of application (not available if requested after admission). No merit-based scholarships for undergraduates. ED applicants can request aid; the package is identical to Regular Decision. The page does not use the words need-blind or need-aware.'),
  ('tulane', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; "Tulane University offers limited need-based financial assistance to international students"; submit the CSS Profile by 15 February. International students must also complete the Certification of Finances form in the Green Wave Portal. The page gives no aid amounts, does not say whether admission is need-aware, and has no merit-scholarship information, so need-aware with limited aid is the closest category rather than a confirmed policy. Tulane offers ''limited need-based financial assistance'' to international students; need-aware/need-blind status is not stated.'),
  ('uc-davis', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UC Davis financial aid says international students may be eligible for scholarships, private loans and short-term loans, and links to institutional/prestigious scholarships and outside scholarships; it does not describe a need-based program for internationals.'),
  ('uc-irvine', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UCI''s international FAQ says it does not offer financial assistance for international students and points to external scholarships.'),
  ('uc-riverside', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International first-years are automatically considered for the Achievement Scholarship for Nonresident Students: up to $89,100 over four years, renewable with a 3.0 GPA each quarter. UCR''s international pages do not describe need-based aid for international students, so no aid policy is recorded.'),
  ('uc-san-diego', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UCSD says international students are not eligible for federal or state financial aid and must prove sufficient funds for a visa. No institutional scholarship program for first-year internationals was found on the pages checked.'),
  ('uc-santa-barbara', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UCSB says financial aid and scholarships for international students are very limited, that aid is primarily for U.S. residents, and that internationals must secure private funding; proof of first-year funding is due to OISS after admission and SIR.'),
  ('uc-santa-cruz', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International students typically are not eligible for federal, state or university need-based aid. Considered automatically for the Undergraduate Deans'' Award ($3,000-$25,000 per year for nonresident/international first-years) and the Regents Scholarship ($5,000 per year for up to four years); no separate application.'),
  ('uchicago', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Committed to meeting 100% of demonstrated need with a loan-free package for admitted applicants who applied for aid. International students are eligible for merit scholarships (partial-tuition) and are considered automatically; no separate application. The page does not state whether international admission is need-blind or need-aware.'),
  ('ucla', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UCLA''s admissions site says it does not award scholarships or financial aid to undergraduates who are not U.S. citizens or permanent residents; admitted internationals must show funds (about $80,739 minimum for fall 2026 entrants). UCLA''s financial aid site says internationals may be eligible only for outside scholarships, private loans and short-term loans.'),
  ('uconn', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance.'),
  ('uf', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Students on F-1/F-2/J-1/J-2 or G-series visas are not eligible for federal aid administered by UF; the page says they may be eligible for private or college-awarded scholarships. No international need-aid program is described.'),
  ('uga', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; The Foundation Fellowship (application due Nov 1) is open to international first-years: $30,000 stipend plus a waiver of the difference between in-state and international tuition. The need-and-merit scholarships listed require Georgia residency and a FAFSA.'),
  ('umass-amherst', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance.'),
  ('umn', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Global Excellence Scholarships are competitive merit scholarships for international freshmen and transfers; all international students who apply by the deadline are automatically considered. Need-based aid for international students is not mentioned on the pages opened. 2026-27 international cost of attendance shown on the page: $67,085 (9 months).'),
  ('unc', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UNC states international students are not eligible for need-based aid and are not considered for academic scholarships; they must be self-funded for their entire studies.'),
  ('upenn', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-aware for international applicants (non-citizens/non-permanent residents of the US, Canada and Mexico); admitted aid recipients get need-based aid covering 100% of demonstrated need. Aid must be requested at the time of application and cannot be added later. No merit aid (awards are need-based).'),
  ('usc', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; USC does not offer need-based financial aid to international applicants, who must document funds for at least the first year. All international applicants who apply by the appropriate deadline are eligible for USC Merit Scholarships (no separate application, no minimum eligibility requirements; highly competitive).'),
  ('ut-austin', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UT''s ISSS lists certain scholarships open to international students, but awards are one-time and several (e.g. General ISSS Financial Aid) require at least two semesters at UT first. UT''s pages opened did not state whether incoming international first-years can receive need-based aid, so no aid policy is recorded.'),
  ('uva', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; UVA states it has no funds for scholarships or loans for international students who are foreign nationals, and does not recommend applying without means to pay; admitted students must submit a Financial Guarantee. Exception: graduates of United World College schools qualify for need-based scholarship support (Davis Foundation Scholarship).'),
  ('uw-madison', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; From the Common Data Set (2025-2026): the college''s own scholarship or grant aid is not available to nonresident undergraduates. The admissions site mentions limited scholarship opportunities for students from particular countries (for example King-Morgridge) and a Wisconsin Scholarship Hub; check eligibility individually.'),
  ('uw-seattle', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; "The UW does not provide financial aid or scholarships to undergraduate international students."'),
  ('vanderbilt', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; International applicants requesting need-based aid are considered on a need-aware basis (need-blind applies only to US citizens and eligible non-citizens). The page''s 100%-of-need pledge is stated for US citizens and eligible non-citizens, not for international students. For fall 2026 Vanderbilt offered aid to 89 international students from 54 countries; awards ranged $16,815-$99,998 per year. International first-years may apply for all merit scholarships (small number of top applicants). Need-based aid requires the CSS Profile or ISFAA.'),
  ('vassar', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Meets the full demonstrated need of all admitted students who apply for aid at the time of application; need-aware for international applicants. International students must apply for aid with their admission application; those admitted without aid are not eligible later. No aid for international transfer applicants.'),
  ('villanova', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Admission for international first-year students is need-aware. Merit scholarships (awarded by Admission, incl. nomination for the Presidential Scholarship) and limited need-based grants are available; no merit or need-based aid for international transfer students.'),
  ('virginia-tech', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-based aid requires a valid FAFSA (US citizen/eligible noncitizen) or Virginia VASA. International students who cannot file either may still apply for college and departmental scholarships via Scholarship Central after applying.'),
  ('wake-forest', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; "Wake Forest University does not offer any need-based financial aid to foreign national students." International students are eligible for most merit scholarships, including full-cost awards (Carswell, Gordon, Reynolds, Stamps); the regular application doubles as the scholarship application. Applicants not given a merit award must show sufficient support on the Confidential Financial Information for International Applicants form before admission is considered. (WFU says it meets 100% of demonstrated need for domestic students.)'),
  ('washu', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Page states WashU meets 100 percent of demonstrated need for all admitted undergraduates; international applicants are eligible for aid only if they apply for it during the admission process. The page does not say whether admission is need-blind or need-aware for international applicants. School Scholarships (up to full tuition, four-year) need no separate application; Signature Scholar Programs need a December 16, 2026 submission for priority.'),
  ('wellesley', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Wellesley is need-blind only for U.S. citizens and permanent residents. For international citizens admission is need-aware and the College can fund only a limited number of awards, but admitted students receive their full calculated need. International applicants must request aid when applying (not accepted after the admission decision). This comes from search-extracted page text because the site blocks automated fetching; confirm with the college.'),
  ('william-mary', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; The international page states that W&M generally does not have scholarships or loan funds for undergraduate international students who are citizens of other countries.'),
  ('williams', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Not need-blind for international applicants, but aid meets 100% of demonstrated need, is guaranteed for all four years, and about 70% of international students receive aid (average award over $90,000). Applicants who may seek aid at any point must answer Yes to the aid question on the application; aid materials are requested only after admission. No merit scholarships are described.'),
  ('wpi', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; Need-aware at the application stage; limited need-based assistance for international first-year and transfer students (CSS Profile due by the admissions deadline). WPI says competitive international applicants typically contribute at least $25,000 per year. Up to two WPI International Leadership Awards per year (up to full tuition and fees, possible $12,000 housing allowance); all admitted fall-entry international students are considered automatically.'),
  ('yale', 'College Scorecard (data released 2026-10-15; IPEDS charges for 2025-26, which match the 2025-26 cost tables published by Berea, Pitzer and Scripps): tuition includes required fees; on-campus cost of attendance; All applicants are evaluated without regard to ability to pay and Yale meets 100% of demonstrated need for all admitted students, including international. Indicate interest in aid on the application; the ISFAA is not accepted in place of Yale''s own aid forms. No merit awards (need-based Yale Scholarship only).')) v(slug, notes)
where i.id = t.institution_id
  and i.slug = v.slug
  and t.year = '2023-2024';

do $$
declare
  ok integer;
begin
  select count(*) into ok
  from public.cost_aid t join public.institutions i on i.id = t.institution_id
  where i.slug in ('american', 'amherst', 'arizona', 'babson', 'barnard', 'binghamton', 'bowdoin', 'brandeis', 'brown', 'buffalo', 'case-western', 'claremont-mckenna', 'clemson', 'columbia', 'cornell', 'cu-boulder', 'drexel', 'duke', 'emory', 'florida-state', 'fordham', 'georgetown', 'gwu', 'harvey-mudd', 'indiana', 'johns-hopkins', 'lehigh', 'miami', 'michigan-state', 'middlebury', 'northeastern', 'northwestern', 'notre-dame', 'ohio-state', 'penn-state', 'pitt', 'pomona', 'princeton', 'rice', 'rit', 'rochester', 'rpi', 'rutgers', 'santa-clara', 'smu', 'stevens', 'stony-brook', 'swarthmore', 'syracuse', 'texas-am', 'tufts', 'tulane', 'uc-davis', 'uc-irvine', 'uc-riverside', 'uc-san-diego', 'uc-santa-barbara', 'uc-santa-cruz', 'uchicago', 'ucla', 'uconn', 'uf', 'uga', 'umass-amherst', 'umn', 'unc', 'upenn', 'usc', 'ut-austin', 'uva', 'uw-madison', 'uw-seattle', 'vanderbilt', 'vassar', 'villanova', 'virginia-tech', 'wake-forest', 'washu', 'wellesley', 'william-mary', 'williams', 'wpi', 'yale')
    and t.year = '2025-2026' and t.notes like 'College Scorecard (data released 2026-10-15;%';
  if ok <> 83 or exists (
    select 1 from public.cost_aid t join public.institutions i on i.id = t.institution_id
    where i.slug in ('american', 'amherst', 'arizona', 'babson', 'barnard', 'binghamton', 'bowdoin', 'brandeis', 'brown', 'buffalo', 'case-western', 'claremont-mckenna', 'clemson', 'columbia', 'cornell', 'cu-boulder', 'drexel', 'duke', 'emory', 'florida-state', 'fordham', 'georgetown', 'gwu', 'harvey-mudd', 'indiana', 'johns-hopkins', 'lehigh', 'miami', 'michigan-state', 'middlebury', 'northeastern', 'northwestern', 'notre-dame', 'ohio-state', 'penn-state', 'pitt', 'pomona', 'princeton', 'rice', 'rit', 'rochester', 'rpi', 'rutgers', 'santa-clara', 'smu', 'stevens', 'stony-brook', 'swarthmore', 'syracuse', 'texas-am', 'tufts', 'tulane', 'uc-davis', 'uc-irvine', 'uc-riverside', 'uc-san-diego', 'uc-santa-barbara', 'uc-santa-cruz', 'uchicago', 'ucla', 'uconn', 'uf', 'uga', 'umass-amherst', 'umn', 'unc', 'upenn', 'usc', 'ut-austin', 'uva', 'uw-madison', 'uw-seattle', 'vanderbilt', 'vassar', 'villanova', 'virginia-tech', 'wake-forest', 'washu', 'wellesley', 'william-mary', 'williams', 'wpi', 'yale') and t.year = '2023-2024'
  ) then
    raise exception 'scorecard cost year: % of 83 rows relabelled, rolling back', ok;
  end if;
end $$;

commit;

